public class ObjectCreationDemo {
    static class Tile { Tile() { System.out.println("constructor"); } }
    public static void main(String[] args) throws Exception {
        Tile direct = new Tile();
        Tile reflected = Tile.class.getDeclaredConstructor().newInstance();
        System.out.println(direct.getClass() == reflected.getClass());
    }
}
